print('loaded songs:', len(main.musicas))
print('generos:', len(main.generos))
print('acordes unicos:', len(main.acordes))
print('TAM_PAGINA:', main.TAM_PAGINA)

# tag distribution
cnt = collections.Counter()
for m in main.musicas.values():
    for t in m.seqs_famosas:
        cnt[t] += 1
print('tag distribution (raw tokens):', dict(cnt))

seqs = [
    (0, ['Bm','G','D','A']),
    (1, ['C','G','Am','F']),
    (2, ['Em','G']),
    (3, ['C','A7','Dm','G7']),
    (4, ['Gm','F']),
    (5, ['C','C7','F','Fm']),
]

def contiguous(seq, tokens):
    n=len(tokens)
    if n==0: return True
    return any(seq[i:i+n]==tokens for i in range(len(seq)-n+1))

def subsequence(seq, tokens):
    it=iter(seq)
    return all(any(x==t for x in it) for t in tokens)

def set_contains(seq, tokens):
    return set(tokens).issubset(set(seq))

def tag_rule(seq, tokens):
    return contiguous(seq, tokens) and set(tokens).issubset(set(seq))

tag_sets={}
for idx,tokens in seqs:
    tag_sets[idx]={m.id_unico_musica for m in main.musicas.values() if str(idx) in m.seqs_famosas}

print('\nidx seq                 tag  contig contig_ci subseq set_contains tag_rule  tag==contig tag==set tag==tag_rule')
for idx,tokens in seqs:
    t=tag_sets[idx]
    c={m.id_unico_musica for m in main.musicas.values() if contiguous(m.cifra,tokens)}
    cci={m.id_unico_musica for m in main.musicas.values() if contiguous([x.lower() for x in m.cifra],[x.lower() for x in tokens])}
    ss={m.id_unico_musica for m in main.musicas.values() if subsequence(m.cifra,tokens)}
    sc={m.id_unico_musica for m in main.musicas.values() if set_contains(m.cifra,tokens)}
    tr={m.id_unico_musica for m in main.musicas.values() if tag_rule(m.cifra,tokens)}
    print(f'{idx}   {",".join(tokens):20} {len(t):4} {len(c):6} {len(cci):9} {len(ss):6} {len(sc):12} {len(tr):8}  {t==c!s:11} {t==sc!s:9} {t==tr!s:11}')

# reproduce generate_data_set.get_famosas on live m.cifra
seqs_script=['bm;g;d;a','c;g;am;f','em;g','c;a7;dm;g7','gm;f','c;c7;f;fm']
def get_famosas(acorde):
    out=[]
    for i,s in enumerate(seqs_script):
        a=acorde.lower()
        if s in a:
            achou=True
            for l in a.split(';'):
                if l not in s.split(';'):
                    achou=False; break
            if achou:
                out.append(str(i))
    return out
mis=0; ex=[]
for m in main.musicas.values():
    fam=get_famosas(';'.join(m.cifra))
    tag=[x for x in m.seqs_famosas if x!='']
    if fam!=tag:
        mis+=1
        if len(ex)<5: ex.append((m.id_unico_musica, tag, fam, m.cifra[:12]))
print('\nget_famosas(live m.cifra) vs tag: mismatches', mis, 'of', len(main.musicas))
for e in ex: print(' ', e)

# compare raw CSV CIFRA string (csv module) vs joined live cifra
rows=list(csv.reader(open('data/top/dataset_final.csv', encoding='utf-8', newline='')))
header=rows[0]; rows=rows[1:]
print('\nCSV header:', header)
print('CSV data rows:', len(rows))
mis_raw=0; ex_raw=[]
for r,m in zip(rows, main.musicas.values()):
    raw=r[8]
    raw_tokens=[] if raw in ('NA','') else [t for t in raw.split(';') if t.strip()!='']
    live=m.cifra
    if raw_tokens!=live:
        mis_raw+=1
        if len(ex_raw)<8: ex_raw.append((m.id_unico_musica, raw_tokens[:10], live[:10]))
print('raw CIFRA tokens vs live m.cifra mismatches:', mis_raw, 'of', len(rows))
for e in ex_raw: print(' ', e)

# empty cifra count and example
empty=sum(1 for m in main.musicas.values() if not m.cifra)
print('songs with empty cifra:', empty)
# acordes vs cifra example
for m in list(main.musicas.values())[:3]:
    print('\nexample', m.id_unico_musica)
    print(' cifra[:12]', m.cifra[:12], 'len', len(m.cifra))
    print(' acordes[:12]', m.acordes[:12], 'len', len(m.acordes), 'unique cifra', len(set(m.cifra)))
